#!/usr/bin/env bun
import { spawnSync } from "child_process";

/**
 * Executes a tool and returns the result.
 * @param filePath The path to the tool to execute.
 * @returns An object containing success status and output/error.
 */
function executeTool(filePath: string) {
  console.log(`Executing tool: ${filePath}`);

  // We use spawnSync to run the tool with bun.
  // This ensures we capture the output and errors in a synchronous way.
  const result = spawnSync("bun", [filePath], {
    encoding: "utf-8",
    shell: true,
  });

  if (result.status === 0) {
    return {
      success: true,
      output: result.stdout?.trim(),
    };
  } else {
    return {
      success: false,
      error: result.stderr?.trim() || result.stdout?.trim() || "Unknown error occurred",
    };
  }
}

// Basic command line interface for manual testing
if (process.argv[2]) {
  const toolPath = process.argv[2];
  const result = executeTool(toolPath);

  if (result.success) {
    console.log("SUCCESS:");
    console.log(result.output);
  } else {
    console.error("FAILURE:");
    console.error(result.error);
    process.exit(1);
  }
} else {
  console.log("Usage: bun executor.ts <path_to_tool>");
}

console.log("Hello from the test tool!");
const a = 10;
const b = 20;
console.log(`The sum of ${a} and ${b} is ${a + b}`);

console.log("This will fail");
const a = 10;
const b = undefined;
console.log(`The sum of ${a} and ${b} is ${a + b}`);

console.log("This will throw");
const a = 10;
const b = null;
console.log(`The sum of ${a} and ${b} is ${a + b}`);
// Wait, 10 + null is 10.
// I need something that throws.
throw new Error("Intentional Failure");

