import fs from "fs";
import path from "path";

function explore() {
  const files = fs.readdirSync(".");
  const categories: Record<string, string[]> = {};

  files.forEach(file => {
    const ext = path.extname(file) || ".no_extension";
    if (!categories[ext]) {
      categories[ext] = [];
    }
    categories[ext].push(file);
  });

  console.log("Workspace Inventory:");
  for (const [ext, files] of Object.entries(categories)) {
    console.log(`[${ext}]: ${files.join(", ")}`);
  }
}

explore();

